// connection_pool.rs - Database Connection Pool
use sqlx::{
    postgres::{PgPoolOptions, PgConnectOptions, PgPool},
    migrate::Migrator,
    ConnectOptions, Row,
};\use std::time::Duration;\use std::sync::Arc;\use tokio::sync::RwLock;\use tracing::{info, warn, error, instrument};\use thiserror::Error;\use serde::{Deserialize, Serialize};\n
#[derive(Error, Debug)]
pub enum DatabaseError {
    #[error("Connection failed: {0}")]
    ConnectionFailed(#[from] sqlx::Error),
    #[error("Migration failed: {0}")]
    MigrationFailed(String),
    #[error("Pool exhausted: no connections available")]
    PoolExhausted,
    #[error("Health check failed: {0}")]
    HealthCheckFailed(String),
    #[error("Configuration error: {0}")]
    ConfigError(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DatabaseConfig {
    pub host: String,
    pub port: u16,
    pub username: String,
    pub password: String,
    pub database: String,
    pub max_connections: u32,
    pub min_connections: u32,
    pub connect_timeout_secs: u64,
    pub idle_timeout_secs: u64,
    pub max_lifetime_secs: u64,
    pub acquire_timeout_secs: u64,
    pub ssl_mode: SslMode,
    pub application_name: String,
    pub run_migrations: bool,
    pub migration_path: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SslMode {
    Disable,
    Allow,
    Prefer,
    Require,
    VerifyCa,
    VerifyFull,
}

impl Default for DatabaseConfig {
    fn default() -> Self {
        Self {
            host: "localhost".to_string(),
            port: 5432,
            username: "postgres".to_string(),
            password: "postgres".to_string(),
            database: "locus".to_string(),
            max_connections: 20,
            min_connections: 5,
            connect_timeout_secs: 10,
            idle_timeout_secs: 600,
            max_lifetime_secs: 1800,
            acquire_timeout_secs: 30,
            ssl_mode: SslMode::Prefer,
            application_name: "locus".to_string(),
            run_migrations: true,
            migration_path: "./migrations".to_string(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PoolMetrics {
    pub total_connections: u32,
    pub idle_connections: u32,
    pub active_connections: u32,
    pub max_connections: u32,
    pub waiting_requests: u32,
    pub total_acquired: u64,
    pub total_released: u64,
    pub total_errors: u64,
    pub avg_acquire_time_ms: f64,
}

#[derive(Debug, Clone)]
pub struct HealthStatus {
    pub healthy: bool,
    pub latency_ms: f64,
    pub last_check: chrono::DateTime<chrono::Utc>,
    pub error: Option<String>,
}

pub struct DatabasePool {
    pool: PgPool,
    config: DatabaseConfig,
    metrics: Arc<RwLock<PoolMetrics>>,
    health_status: Arc<RwLock<HealthStatus>>,
    migrator: Option<Migrator>,
}

impl DatabasePool {
    #[instrument(skip(config))]
    pub async fn new(config: DatabaseConfig) -> Result<Self, DatabaseError> {
        let connect_options = Self::build_connect_options(&config);

        let pool = PgPoolOptions::new()
            .max_connections(config.max_connections)
            .min_connections(config.min_connections)
            .acquire_timeout(Duration::from_secs(config.acquire_timeout_secs))
            .idle_timeout(Duration::from_secs(config.idle_timeout_secs))
            .max_lifetime(Duration::from_secs(config.max_lifetime_secs))
            .connect_with(connect_options)
            .await?;

        let migrator = if config.run_migrations {
            Some(Migrator::new(std::path::Path::new(&config.migration_path)).await
                .map_err(|e| DatabaseError::MigrationFailed(e.to_string()))?)
        } else {
            None
        };

        if let Some(ref m) = migrator {
            m.run(&pool).await.map_err(|e| DatabaseError::MigrationFailed(e.to_string()))?;
            info!("Database migrations applied successfully");
        }

        let metrics = Arc::new(RwLock::new(PoolMetrics {
            total_connections: config.max_connections,
            idle_connections: config.min_connections,
            active_connections: 0,
            max_connections: config.max_connections,
            waiting_requests: 0,
            total_acquired: 0,
            total_released: 0,
            total_errors: 0,
            avg_acquire_time_ms: 0.0,
        }));

        let health_status = Arc::new(RwLock::new(HealthStatus {
            healthy: true,
            latency_ms: 0.0,
            last_check: chrono::Utc::now(),
            error: None,
        }));

        let db = Self {
            pool,
            config,
            metrics,
            health_status,
            migrator,
        };

        db.start_health_check_task().await;
        db.start_metrics_collection_task().await;

        Ok(db)
    }

    fn build_connect_options(config: &DatabaseConfig) -> PgConnectOptions {
        let mut opts = PgConnectOptions::new()
            .host(&config.host)
            .port(config.port)
            .username(&config.username)
            .password(&config.password)
            .database(&config.database)
            .application_name(&config.application_name)
            .connect_timeout(Duration::from_secs(config.connect_timeout_secs));

        opts = match config.ssl_mode {
            SslMode::Disable => opts.ssl_mode(sqlx::postgres::PgSslMode::Disable),
            SslMode::Allow => opts.ssl_mode(sqlx::postgres::PgSslMode::Allow),
            SslMode::Prefer => opts.ssl_mode(sqlx::postgres::PgSslMode::Prefer),
            SslMode::Require => opts.ssl_mode(sqlx::postgres::PgSslMode::Require),
            SslMode::VerifyCa => opts.ssl_mode(sqlx::postgres::PgSslMode::VerifyCa),
            SslMode::VerifyFull => opts.ssl_mode(sqlx::postgres::PgSslMode::VerifyFull),
        };

        opts
    }

    pub fn pool(&self) -> &PgPool {
        &self.pool
    }

    #[instrument(skip(self))]
    pub async fn execute(&self, query: &str) -> Result<u64, DatabaseError> {
        let start = std::time::Instant::now();
        let result = sqlx::query(query).execute(&self.pool).await;
        self.record_metrics(start.elapsed(), result.is_err()).await;
        result.map(|r| r.rows_affected()).map_err(Into::into)
    }

    #[instrument(skip(self))]
    pub async fn fetch_one<T>(&self, query: &str) -> Result<T, DatabaseError>
    where
        T: for<'r> sqlx::FromRow<'r, sqlx::postgres::PgRow> + Send + Unpin,
    {
        let start = std::time::Instant::now();
        let result = sqlx::query_as::<_, T>(query).fetch_one(&self.pool).await;
        self.record_metrics(start.elapsed(), result.is_err()).await;
        result.map_err(Into::into)
    }

    #[instrument(skip(self))]
    pub async fn fetch_all<T>(&self, query: &str) -> Result<Vec<T>, DatabaseError>
    where
        T: for<'r> sqlx::FromRow<'r, sqlx::postgres::PgRow> + Send + Unpin,
    {
        let start = std::time::Instant::now();
        let result = sqlx::query_as::<_, T>(query).fetch_all(&self.pool).await;
        self.record_metrics(start.elapsed(), result.is_err()).await;
        result.map_err(Into::into)
    }

    #[instrument(skip(self))]
    pub async fn fetch_optional<T>(&self, query: &str) -> Result<Option<T>, DatabaseError>
    where
        T: for<'r> sqlx::FromRow<'r, sqlx::postgres::PgRow> + Send + Unpin,
    {
        let start = std::time::Instant::now();
        let result = sqlx::query_as::<_, T>(query).fetch_optional(&self.pool).await;
        self.record_metrics(start.elapsed(), result.is_err()).await;
        result.map_err(Into::into)
    }

    pub async fn begin_transaction(&self) -> Result<sqlx::Transaction<'_, sqlx::Postgres>, DatabaseError> {
        self.pool.begin().await.map_err(Into::into)
    }

    async fn record_metrics(&self, duration: Duration, is_error: bool) {
        let mut metrics = self.metrics.write().await;
        if is_error {
            metrics.total_errors += 1;
        }
        let acquire_ms = duration.as_millis() as f64;
        let total = metrics.total_acquired + metrics.total_released + 1;
        metrics.avg_acquire_time_ms = 
            (metrics.avg_acquire_time_ms * (total - 1) as f64 + acquire_ms) / total as f64;
    }

    async fn start_health_check_task(&self) {
        let pool = self.pool.clone();
        let health_status = self.health_status.clone();
        let interval_secs = 30;

        tokio::spawn(async move {
            let mut interval = tokio::time::interval(Duration::from_secs(interval_secs));
            loop {
                interval.tick().await;
                let start = std::time::Instant::now();

                let result = sqlx::query("SELECT 1").fetch_one(&pool).await;

                let mut status = health_status.write().await;
                match result {
                    Ok(_) => {
                        status.healthy = true;
                        status.latency_ms = start.elapsed().as_millis() as f64;
                        status.error = None;
                    }
                    Err(e) => {
                        status.healthy = false;
                        status.latency_ms = start.elapsed().as_millis() as f64;
                        status.error = Some(e.to_string());
                        error!("Database health check failed: {}", e);
                    }
                }
                status.last_check = chrono::Utc::now();
            }
        });
    }

    async fn start_metrics_collection_task(&self) {
        let pool = self.pool.clone();
        let metrics = self.metrics.clone();
        let config = self.config.clone();

        tokio::spawn(async move {
            let mut interval = tokio::time::interval(Duration::from_secs(10));
            loop {
                interval.tick().await;

                let size = pool.size();
                let idle = pool.num_idle();

                let mut m = metrics.write().await;
                m.total_connections = size;
                m.idle_connections = idle;
                m.active_connections = size.saturating_sub(idle);
            }
        });
    }

    pub async fn get_metrics(&self) -> PoolMetrics {
        self.metrics.read().await.clone()
    }

    pub async fn get_health_status(&self) -> HealthStatus {
        self.health_status.read().await.clone()
    }

    pub async fn close(&self) {
        self.pool.close().await;
        info!("Database pool closed");
    }
}

impl Drop for DatabasePool {
    fn drop(&mut self) {
        // Pool closes automatically on drop
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use sqlx::Row;

    #[tokio::test]
    #[ignore]
    async fn test_connection_pool() {
        let config = DatabaseConfig {
            host: "localhost".to_string(),
            port: 5432,
            username: "postgres".to_string(),
            password: "postgres".to_string(),
            database: "test".to_string(),
            ..Default::default()
        };

        let pool = DatabasePool::new(config).await.unwrap();

        let result: (i32,) = pool.fetch_one("SELECT 1 as val").await.unwrap();
        assert_eq!(result.0, 1);

        let health = pool.get_health_status().await;
        assert!(health.healthy);

        let metrics = pool.get_metrics().await;
        assert!(metrics.total_connections > 0);

        pool.close().await;
    }
}
